**Fix:** Gate all data endpoints behind authentication middleware, and never return more fields than the caller is authorized to see.

```js
// ✅ Fixed — JWT auth middleware guards the route
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
}

app.get('/users', requireAuth, (req, res) => {
  // Only return fields appropriate for the caller's role
  const safeUsers = users.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});
