const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

// ✅ Global error handler — MUST be defined last, after all routes
app.use((err, req, res, next) => {
  // Log the full error server-side only
  logger.error({ err, url: req.url, method: req.method }, 'Unhandled error');

  // Return nothing useful to the caller
  res.status(err.status || 500).json({ error: 'An unexpected error occurred.' });
});

// ✅ Catch async errors by wrapping handlers (or use express-async-errors)
const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

app.get('/users', requireAuth, asyncHandler(async (req, res) => {
  const users = await getUsersFromDB();
  res.json(users);
}));
```

