const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
const { param, validationResult } = require('express-validator');
const jwt       = require('jsonwebtoken');

const app  = express();
const PORT = parseInt(process.env.PORT, 10) || 3000;

// ── Security headers ──────────────────────────────────────────────────────────
app.use(helmet());

// ── CORS ──────────────────────────────────────────────────────────────────────
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  methods: ['GET'],
  credentials: true,
}));

// ── Body parsing (with size limit) ────────────────────────────────────────────
app.use(express.json({ limit: '10kb' }));

// ── Rate limiting ─────────────────────────────────────────────────────────────
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100, standardHeaders: true }));

// ── Request logging ───────────────────────────────────────────────────────────
app.use(morgan('combined'));

// ── Auth middleware ───────────────────────────────────────────────────────────
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Forbidden' });
    req.user = user;
    next();
  });
};

// ── Routes ────────────────────────────────────────────────────────────────────
app.get('/health', (_req, res) => res.status(200).json({ status: 'ok' }));

app.get('/users', authenticateToken, (_req, res) => {
  // In production: query DB; never hardcode data or return unsanitized rows
  res.json([
    { id: 1, name: 'Alice' }, // email omitted — return only necessary fields
    { id: 2, name: 'Bob'   },
  ]);
});

// ── Global error handler (must be last) ───────────────────────────────────────
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  });
});

app.listen(PORT, '127.0.0.1', () => console.log(`Server on port ${PORT}`));
module.exports = app;
